using Microsoft.VisualBasic.ApplicationServices;
using System.ComponentModel;
using System.Diagnostics;

namespace Lab3
{
    public partial class Form1 : Form
    {
        private CellularAutomaton cells;
        private bool isDragging = false;
        private int currentStatus = 3;

        public Form1()
        {
            InitializeComponent();
            button2.Enabled = false;
            radioButton4.Checked = true;
            radioButton1.CheckedChanged += ChangeCurrentStatus;
            radioButton2.CheckedChanged += ChangeCurrentStatus;
            radioButton3.CheckedChanged += ChangeCurrentStatus;
            radioButton4.CheckedChanged += ChangeCurrentStatus;
            radioButton5.CheckedChanged += ChangeCurrentStatus;
            cells = new CellularAutomaton((int)numericUpDown3.Value);
            typeof(Panel).GetProperty("DoubleBuffered", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)?.SetValue(panel1, true);
            panel1.MouseDown += new MouseEventHandler(panel1_MouseDown);
            panel1.MouseMove += new MouseEventHandler(panel1_MouseMove);
            panel1.MouseUp += new MouseEventHandler(panel1_MouseUp);
            panel1.Invalidate();
        }

        private void button1_Click(object sender, EventArgs e)
        {
            timer1.Start();
            button1.Enabled = false;
            button2.Enabled = true;
            button3.Enabled = false;
            button4.Enabled = false;
            numericUpDown3.Enabled = false;
        }

        private void button2_Click(object sender, EventArgs e)
        {
            timer1.Stop();
            button1.Enabled = true;
            button2.Enabled = false;
            button3.Enabled = true;
            button4.Enabled = true;
            numericUpDown3.Enabled = true;
        }

        private void button3_Click(object sender, EventArgs e)
        {
            cells.DoStep();
            panel1.Invalidate();
        }

        private void button4_Click(object sender, EventArgs e)
        {
            int x = (int)numericUpDown1.Value;
            int y = (int)numericUpDown2.Value;
            cells.SetFire(x - 1, y - 1);
            panel1.Invalidate();
        }

        private void timer1_Tick(object sender, EventArgs e)
        {
            cells.DoStep();
            panel1.Invalidate();
        }

        private void panel1_Paint(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            for (int i = 0; i < 120; i++)
            {
                for (int j = 0; j < 120; j++)
                {
                    Color CellColor;
                    if (cells.GetAtPos(i, j) == 0) CellColor = Color.Yellow;
                    else if (cells.GetAtPos(i, j) == 1) CellColor = Color.Green;
                    else if (cells.GetAtPos(i, j) == 2) CellColor = Color.Red;
                    else if (cells.GetAtPos(i, j) == 3) CellColor = Color.Blue;
                    else CellColor = Color.Purple;
                    SolidBrush brush = new SolidBrush(CellColor);
                    g.FillRectangle(brush, j * 5, i * 5, 5, 5);
                }
            }
        }

        private void numericUpDown3_ValueChanged(object sender, EventArgs e)
        {
            cells.SetHumidity((int)numericUpDown3.Value);
        }

        private void panel1_MouseDown(object sender, MouseEventArgs e)
        {
            if (e.Button == MouseButtons.Left)
            {
                isDragging = true;
                SetCellFromCoordinates(e.X, e.Y);
            }
        }

        private void panel1_MouseMove(object sender, MouseEventArgs e)
        {
            if (isDragging && e.Button == MouseButtons.Left)
            {
                SetCellFromCoordinates(e.X, e.Y);
            }
        }

        private void panel1_MouseUp(object sender, MouseEventArgs e)
        {
            isDragging = false;
        }

        private void SetCellFromCoordinates(int x, int y)
        {
            int row = (int)(y / 5);
            int column = (int)(x / 5);
            cells.ChangeStatus(row, column, currentStatus);
            panel1.Invalidate();
        }

        private void ChangeCurrentStatus(object sender, EventArgs e)
        {
            if (radioButton1.Checked) currentStatus = 0;
            else if (radioButton2.Checked) currentStatus = 1;
            else if (radioButton3.Checked) currentStatus = 2;
            else if (radioButton4.Checked) currentStatus = 3;
            else currentStatus = 4;
        }
    }

