            for (int i = 0; i < 120; i++) 
            {
                for (int j = 0; j < 120; j++) 
                {
                    int CellStatus = Grid[i, j];
                    if (CellStatus == 0) 
                    {
                        if (Rand.NextDouble() < (lightningChance * (1 - humidity / 100.0)))
                        {
                            nextStep[i, j] = 4;
                            continue;
                        }
                        int NeighborsAmount = 0;
                        int TreesAmount = 0;
                        double GrowthChance = 0.1 + (humidity / 200.0);
                        for (int k = 0; k < 8; k++) 
                        {
                            if ((i + HorizontalChecks[k] >= 0) && (i + HorizontalChecks[k] <= 119) && (j + VerticalChecks[k] >= 0) && (j + VerticalChecks[k] <= 119))
                            {
                                NeighborsAmount += 1;
                                if (Grid[i + HorizontalChecks[k], j + VerticalChecks[k]] == 1)
                                {
                                    TreesAmount += 1;
                                }
                            }
                        }
                        GrowthChance += (TreesAmount / (double)NeighborsAmount) / 2.5;
                        if (Rand.NextDouble() < GrowthChance) nextStep[i, j] = 1;
                    }
                    else if (CellStatus == 1)
                    {
                        if (Rand.NextDouble() < (lightningChance * (1 - humidity / 100.0)))
                        {
                            nextStep[i, j] = 4;
                            continue;
                        }
                        int NeighborsAmount = 0;
                        int FireAmount = 0;
                        double IgniteChance = 0.25;
                        for (int k = 0; k < 8; k++)
                        {
                            if ((i + HorizontalChecks[k] >= 0) && (i + HorizontalChecks[k] <= 119) && (j + VerticalChecks[k] >= 0) && (j + VerticalChecks[k] <= 119))
                            {
                                NeighborsAmount += 1;
                                if (Grid[i + HorizontalChecks[k], j + VerticalChecks[k]] == 2)
                                {
                                    FireAmount += 1;
                                }
                            }
                        }
                        IgniteChance += (FireAmount / (double)NeighborsAmount) / (4 / 3.0);
                        IgniteChance *= 1 - (humidity / 100.0);
                        if (FireAmount == 0) IgniteChance = 0;
                        if (Rand.NextDouble() < IgniteChance) nextStep[i, j] = 2;
                    }
                    else if (CellStatus == 2)
                    {
                        nextStep[i, j] = 0;
                    }
                    else if (CellStatus == 3)
                    {
                        nextStep[i, j] = 3;
                    }
                    else if (CellStatus == 4)
                    {
                        if (Rand.NextDouble() < (1 - humidity / 100.0)) nextStep[i, j] = 2;
                        else nextStep[i, j] = 0;
                    }
                }
            }
            Grid = nextStep;
        }

        public void SetFire(int x, int y)
        {
            if (Grid[x, y] != 3) Grid[x, y] = 2;
        }

        public void SetHumidity(int value)
        {
            humidity = value;
        }

        public int GetAtPos(int x, int y)
        {
            return Grid[x, y];
        }

        public void ChangeStatus(int x, int y, int status)
        {
            Grid[x, y] = status;
        }
    }
}
